# Surah Al-A'raf (chapter 7) — part 19: ayat 185-194 (IDs 1139-1148)
SURAH = 7

ENTRIES = {
1139: (
"کیا — وہ — آسمانوں اور زمین کی بادشاہی — میں — اور — جو کچھ اللہ نے — کسی چیز کو — پیدا کیا — نظر نہیں ڈالتے — اور — یہ کہ — عنقریب — ان کی — میعاد — قریب آ سکتی ہے — پس — اس — کے بعد — وہ — کس — بات پر — ایمان لائیں گے",
"""۱۔ کائنات پر نظر — ایمان کی دلیل۔
۲۔ ’’أَوَلَمْ يَنظُرُوا فِي مَلَكُوتِ السَّمَاوَاتِ وَالْأَرْضِ وَمَا خَلَقَ اللَّهُ مِن شَيْءٍ وَأَنْ عَسَىٰ أَن يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ‘‘ — کیا — وہ — آسمانوں اور زمین کی بادشاہی — میں — اور — جو کچھ اللہ نے — کسی چیز کو — پیدا کیا — نظر نہیں ڈالتے — اور — یہ کہ — عنقریب — ان کی — میعاد — قریب آ سکتی ہے — پس — اس — کے بعد — وہ — کس — بات پر — ایمان لائیں گے — یعنی کائنات کی سادگی اور عظمت — اللہ کے وجود کی واضح دلیل ہے۔
۳۔ عملی سبق: کائنات پر غور — ایمان کو — پختہ کرتا ہے۔"""
),
1140: (
"جسے — اللہ — گمراہ کرے — اس کا — کوئی ہدایت دہندہ نہیں — اور وہ — انہیں — ان کی سرکشی میں — بھٹکتے رہنے دیتا ہے",
"""۱۔ اللہ کی طرف سے گمراہی — کسی کی ہدایت سے ممکن نہیں۔
۲۔ ’’مَن يُضْلِلِ اللَّهُ فَلَا هَادِيَ لَهُ وَيَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ‘‘ — جسے — اللہ — گمراہ کرے — اس کا — کوئی ہدایت دہندہ نہیں — اور وہ — انہیں — ان کی سرکشی میں — بھٹکتے رہنے دیتا ہے — یعنی سرکشی — اللہ کی حمایت سے محرومی کی وہ حالت ہے جس میں — ہدایت ممکن نہیں رہتی۔
۳۔ عملی سبق: سرکشی سے بچو؛ ہدایت اللہ سے مانگو۔"""
),
1141: (
"وہ — تم سے — قیامت کے بارے میں پوچھتے ہیں — کہ — اس کا وقوع — کب ہو گا — کہدو — اس — کا علم — صرف — میرے رب — کے پاس ہے — وہی — اسے — اس کے — وقت پر واضح کرتا ہے — وہ — آسمانوں اور زمین میں — بھاری ہے — تمہارے پاس — نہیں آئے گی — مگر — اچانک — وہ — تم سے اس — طرح پوچھتے ہیں — گویا — تو — اس سے — پوری واقف ہے — کہدو — اس کا علم — صرف اللہ — کے پاس ہے — لیکن — اکثر لوگ — نہیں جانتے",
"""۱۔ قیامت کا وقت — کسی کو نہیں معلوم۔
۲۔ ’’يَسْأَلُونَكَ عَنِ السَّاعَۃِ أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّي لَا يُجَلِّيهَا لِوَقْتِهَا إِلَّا هُوَ ثَقُلَتْ فِي السَّمَاوَاتِ وَالْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَۃً يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ اللَّهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — وہ — تم سے — قیامت کے بارے میں پوچھتے ہیں — کہ — اس کا وقوع — کب ہو گا — کہدو — اس — کا علم — صرف — میرے رب — کے پاس ہے — وہی — اسے — اس کے — وقت پر واضح کرتا ہے — وہ — آسمانوں اور زمین میں — بھاری ہے — تمہارے پاس — نہیں آئے گی — مگر — اچانک — وہ — تم سے اس — طرح پوچھتے ہیں — گویا — تو — اس سے — پوری واقف ہے — کہدو — اس کا علم — صرف اللہ — کے پاس ہے — لیکن — اکثر لوگ — نہیں جانتے — یعنی قیامت کا صحیح وقت — کسی نبیؐ اور ولی کو بھی نہیں معلوم۔
۳۔ عملی سبق: قیامت کے وقت کی فکر نہ کرو؛ تیاری کرو۔"""
),
1142: (
"کہدو — میں — اپنے لیے — نہ — کوئی نفع — کا مالک ہوں — اور نہ — نقصان — مگر — جو — اللہ چاہے — اور — اگر — میں — غیب — جانتا — تو — میں — بھلائی — بہت — کر لیتا — اور — مجھے کوئی تکلیف — نہ ہوتی — میں — نہیں ہوں — مگر — ایک ڈرانے والے اور خوش خبری دینے والے — اس — قوم — کے لیے — جو ایمان لائے",
"""۱۔ نبیؐ کا علم غیب — صرف اللہ کی اجازت سے۔
۲۔ ’’قُل لَّا أَمْلِكُ لِنَفْسِي نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لَاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ‘‘ — کہدو — میں — اپنے لیے — نہ — کوئی نفع — کا مالک ہوں — اور نہ — نقصان — مگر — جو — اللہ چاہے — اور — اگر — میں — غیب — جانتا — تو — میں — بھلائی — بہت — کر لیتا — اور — مجھے کوئی تکلیف — نہ ہوتی — میں — نہیں ہوں — مگر — ایک ڈرانے والے اور خوش خبری دینے والے — اس — قوم — کے لیے — جو ایمان لائے — یعنی نبیؐ — بھی — نہ — نفع کے مالک ہیں — نہ نقصان کے — نہ اکیلے غیب کے — صرف اللہ کے دیے ہوئے علم — کے تابع ہیں۔
۳۔ شیعہ عقائد میں نبیؐ اور ائمہؑ کو — اللہ کے دیے ہوئے — علم غیب کا کچھ حصہ حاصل ہوتا ہے — مگر وہ — اللہ ہی کے — تابع ہے۔
۴۔ عملی سبق: نبیؐ کی ذمہ داری — دعوت اور خوش خبری — ہے۔"""
),
1143: (
"وہی — جس نے — تمہیں — ایک — نفس — سے پیدا کیا — اور — اسی سے — اس کی — بیوی — بنائی — تاکہ — وہ — اس سے — سکون پائے — پس — جب — اس — نے — اس سے — صحبت کی — تو وہ — ایک — ہلکا بوجھ — اٹھا — وہ — اسے — لیے پھرتی رہی — پھر — جب — وہ بھاری ہو گئی — تو — دونوں — نے — اللہ — کو — اپنا — رب پکارا — اگر — تو — ہمیں — ایک — تندرست — بچہ دے — ہم — ضرور — شکر گزار — ہوں گے",
"""۱۔ ایک نفس — اور اسے سے زوجہ — اللہ کی نشانی۔
۲۔ ’’هُوَ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَۃٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّاهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِ فَلَمَّا أَثْقَلَت دَّعَوَا اللَّهَ رَبَّهُمَا لَئِنْ آتَيْتَنَا صَالِحًا لَّنَكُونَنَّ مِنَ الشَّاكِرِينَ‘‘ — وہی — جس نے — تمہیں — ایک — نفس — سے پیدا کیا — اور — اسی سے — اس کی — بیوی — بنائی — تاکہ — وہ — اس سے — سکون پائے — پس — جب — اس — نے — اس سے — صحبت کی — تو وہ — ایک — ہلکا بوجھ — اٹھا — وہ — اسے — لیے پھرتی رہی — پھر — جب — وہ بھاری ہو گئی — تو — دونوں — نے — اللہ — کو — اپنا — رب پکارا — اگر — تو — ہمیں — ایک — تندرست — بچہ دے — ہم — ضرور — شکر گزار — ہوں گے — یعنی ایک نفس سے — جوڑا بنا کر — سکون اور نسل — دونوں کا نظام قائم ہے۔
۳۔ عملی سبق: اولاد اللہ کی نعمت ہے؛ اس پر — شکر — کرو۔"""
),
1144: (
"پس — جب — اللہ — نے — انہیں — ایک تندرست — بچہ دیا — تو — انہوں نے — ان میں سے — جو — دیا تھا — اس میں — اس کے — شریک — بنا لیے — پس — اللہ — اس سے — پاک ہے — جس کو وہ — شریک — بناتے ہیں",
"""۱۔ شکر کے بجائے — شرک — سب سے بڑا جرم۔
۲۔ ’’فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا فَتَعَالَى اللَّهُ عَمَّا يُشْرِكُونَ‘‘ — پس — جب — اللہ — نے — انہیں — ایک تندرست — بچہ دیا — تو — انہوں نے — ان میں سے — جو — دیا تھا — اس میں — اس کے — شریک — بنا لیے — پس — اللہ — اس سے — پاک ہے — جس کو وہ — شریک — بناتے ہیں — یعنی اولاد ملنے کے بعد — اللہ کی جگہ — دوسروں کو — معبود بنانا — سراسر ناشکری ہے۔
۳۔ عملی سبق: نعمت — ملنے پر — صرف اللہ کا شکر کرو؛ کسی کو شریک نہ بناؤ۔"""
),
1145: (
"کیا — وہ — ایسی چیزوں کو — شریک — بناتے ہیں — جو — کچھ نہیں بناتی — اور — وہ — خود — بنائی جاتی ہیں",
"""۱۔ بت — بے کار — دلیل۔
۲۔ ’’أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْئًا وَهُمْ يُخْلَقُونَ‘‘ — کیا — وہ — ایسی چیزوں کو — شریک — بناتے ہیں — جو — کچھ نہیں بناتی — اور — وہ — خود — بنائی جاتی ہیں — یعنی جو — خود — مخلوق ہے — وہ — خالق — نہیں ہو سکتی۔
۳۔ عملی سبق: مخلوق کو — خالق — نہ سمجھو۔"""
),
1146: (
"اور — نہ — وہ — ان کی مدد — کر سکتی ہیں — اور نہ — خود — اپنے آپ کو — مدد دے سکتی ہیں",
"""۱۔ بت — نہ — کسی کی مدد — نہ — اپنی۔
۲۔ ’’وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَا أَنفُسَهُمْ يَنصُرُونَ‘‘ — اور — نہ — وہ — ان کی مدد — کر سکتی ہیں — اور نہ — خود — اپنے آپ کو — مدد دے سکتی ہیں — یعنی بت — مکمل — بے بس ہیں۔
۳۔ عملی سبق: بے بس چیزوں پر — تکیہ — خود تباہی ہے۔"""
),
1147: (
"اور — اگر — تم — انہیں — ہدایت — کی دعوت دے — وہ — تمہارا پیچھ نہیں کرتے — تمہارے لیے یکساں ہے — تم انہیں بلاؤ — یا — تم — خاموش رہو",
"""۱۔ بت — ہدایت بھی نہیں دے سکتے۔
۲۔ ’’وَإِن تَدْعُوهُمْ إِلَى الْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَاءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَامِتُونَ‘‘ — اور — اگر — تم — انہیں — ہدایت — کی دعوت دے — وہ — تمہارا پیچھ نہیں کرتے — تمہارے لیے یکساں ہے — تم انہیں بلاؤ — یا — تم — خاموش رہو — یعنی بت — نہ جواب دیتے ہیں — نہ — راستہ دکھاتے ہیں۔
۳۔ عملی سبق: بے جان چیزوں سے — مدد — مانگنا بے سود ہے۔"""
),
1148: (
"بے شک — جن کو تم — اللہ کے علاوہ — پکارتے ہو — وہ — تمہارے جیسے بندے ہیں — پس — انہیں بلاؤ — پس — وہ — تمہاری — پکار کا جواب دیں — اگر — تم سچے ہو",
"""۱۔ پجے ہوئے — تمہارے جیسے — بندے ہیں — بس۔
۲۔ ’’إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ عِبَادٌ أَمْثَالُكُمْ فَادْعُوهُمْ فَلْيَسْتَجِيبُوا لَكُمْ إِن كُنتُمْ صَادِقِينَ‘‘ — بے شک — جن کو تم — اللہ کے علاوہ — پکارتے ہو — وہ — تمہارے جیسے بندے ہیں — پس — انہیں بلاؤ — پس — وہ — تمہاری — پکار کا جواب دیں — اگر — تم سچے ہو — یعنی جو لوگ — خدائی کے دعوے دار ہیں — وہ — تمہارے جیسے انسانی بندے ہیں — خود — تو — جواب دیں گے۔
۳۔ عملی سبق: صرف اللہ — جواب دینے والا ہے؛ اسی کو پکارو۔"""
),
}
